import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { io } from 'socket.io-client';
import { fetchStats, fetchFraudLogs, fetchTrades } from '../services/api';

function StatCard({ label, value, sub, color = '#a3e635', alert = false }) {
  return (
    <div className={`glass card-hover ${alert ? 'fraud-pulse' : ''}`} style={{ padding: 24 }}>
      <div style={{ color: '#6b7280', fontSize: 11, fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 10 }}>{label}</div>
      <div style={{ fontSize: 32, fontWeight: 900, color, textShadow: `0 0 16px ${color}44`, marginBottom: 6 }}>{value ?? '—'}</div>
      {sub && <div style={{ color: '#4b5563', fontSize: 12 }}>{sub}</div>}
    </div>
  );
}

function MiniGraph({ logs }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !logs.length) return;
    const ctx = canvas.getContext('2d');
    const W = canvas.width = canvas.offsetWidth * 2;
    const H = canvas.height = 120;
    ctx.clearRect(0, 0, W, H);
    const scores = logs.slice(0, 20).map(l => l.risk_score || 0).reverse();
    const max    = Math.max(...scores, 100);
    const step   = W / (scores.length - 1);
    ctx.beginPath();
    scores.forEach((s, i) => {
      const x = i * step, y = H - (s / max) * (H - 10) - 5;
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.strokeStyle = '#a3e635';
    ctx.lineWidth   = 3;
    ctx.shadowColor = '#a3e635';
    ctx.shadowBlur  = 8;
    ctx.stroke();
    // fill
    ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath();
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, 'rgba(163,230,53,0.15)');
    grad.addColorStop(1, 'rgba(163,230,53,0)');
    ctx.fillStyle = grad;
    ctx.fill();
  }, [logs]);
  return <canvas ref={canvasRef} style={{ width: '100%', height: 60, display: 'block' }} />;
}

export default function DashboardPage() {
  const navigate = useNavigate();
  const [stats,  setStats]  = useState(null);
  const [logs,   setLogs]   = useState([]);
  const [trades, setTrades] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading,setLoading]= useState(true);

  useEffect(() => {
    Promise.all([fetchStats(), fetchFraudLogs(), fetchTrades()])
      .then(([s, l, t]) => {
        setStats(s);
        setLogs(Array.isArray(l) ? l : []);
        setTrades(Array.isArray(t) ? t : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));

    const socket = io('http://localhost:5000', { transports: ['websocket'] });
    socket.on('fraud_alert', (data) => {
      const d = Array.isArray(data) ? data[0] : data;
      setAlerts(prev => [d, ...prev].slice(0, 5));
    });
    return () => socket.disconnect();
  }, []);

  const riskBadge = (score) => {
    if (score >= 70) return <span className="badge badge-high">HIGH</span>;
    if (score >= 40) return <span className="badge badge-medium">MED</span>;
    return <span className="badge badge-low">LOW</span>;
  };

  const statCards = [
    { label: 'Total Trades',     value: stats?.total_trades?.toLocaleString(),  sub: 'All time',           color: '#a3e635' },
    { label: 'Fraud Rings',      value: stats?.fraud_rings_detected,             sub: 'Active cycles',      color: '#ef4444', alert: !!alerts.length },
    { label: 'High Risk Traders',value: stats?.high_risk_traders,               sub: 'Score < 40',         color: '#f59e0b' },
    { label: 'Monitored Traders',value: stats?.total_traders,                   sub: 'In system',          color: '#a3e635' },
  ];

  return (
    <div style={{ background: '#080808', minHeight: '100vh', padding: '32px' }} className="grid-bg">
      <div style={{ maxWidth: 1400, margin: '0 auto' }}>

        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 32 }}>
          <div>
            <h1 style={{ fontSize: 26, fontWeight: 800, letterSpacing: '-0.02em', marginBottom: 4 }}>
              TraceNet <span className="neon">Dashboard</span>
            </h1>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <div className="blink" style={{ width: 6, height: 6, borderRadius: '50%', background: '#a3e635' }} />
              <span style={{ color: '#6b7280', fontSize: 13 }}>Live monitoring active</span>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button className="btn-outline" onClick={() => navigate('/fraud')} style={{ padding: '9px 18px', fontSize: 13 }}>Fraud Engine</button>
            <button className="btn-outline" onClick={() => navigate('/traders')} style={{ padding: '9px 18px', fontSize: 13 }}>Traders</button>
          </div>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '80px', color: '#4b5563' }}>
            <div className="neon" style={{ fontSize: 32, marginBottom: 12 }}>⟳</div>
            <div>Loading dashboard data...</div>
          </div>
        ) : (
          <>
            {/* Stat cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 16, marginBottom: 24 }}>
              {statCards.map((s, i) => <StatCard key={i} {...s} />)}
            </div>

            {/* Live alerts banner */}
            {alerts.length > 0 && (
              <div className="fraud-pulse" style={{ background: 'rgba(239,68,68,0.06)', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 12, padding: '14px 20px', marginBottom: 24, display: 'flex', alignItems: 'center', gap: 16 }}>
                <div className="blink" style={{ width: 8, height: 8, borderRadius: '50%', background: '#ef4444', flexShrink: 0 }} />
                <div style={{ flex: 1 }}>
                  <span style={{ color: '#f87171', fontWeight: 700, fontSize: 13 }}>🔴 Live Alert: </span>
                  <span style={{ color: '#fca5a5', fontSize: 13 }}>
                    {alerts[0].reason || `Fraud ring detected — Risk Score: ${alerts[0].risk_score || alerts[0].confidence}`}
                  </span>
                </div>
                <span style={{ color: '#6b7280', fontSize: 12 }}>{alerts.length} alert{alerts.length > 1 ? 's' : ''} total</span>
              </div>
            )}

            {/* Main grid */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: 20, marginBottom: 20 }}>

              {/* Recent Trades */}
              <div className="glass" style={{ overflow: 'hidden' }}>
                <div style={{ padding: '20px 20px 16px', borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ fontWeight: 700, fontSize: 15 }}>Recent Trades</div>
                  <button className="btn-ghost" style={{ fontSize: 12 }} onClick={() => navigate('/transactions')}>View all →</button>
                </div>
                <div className="scroll-y" style={{ maxHeight: 360 }}>
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Trade ID</th><th>Stock</th><th>Seller</th><th>Buyer</th><th>Price</th><th>Risk</th>
                      </tr>
                    </thead>
                    <tbody>
                      {trades.slice(0, 15).map((t, i) => (
                        <tr key={i}>
                          <td style={{ color: '#4b5563', fontFamily: 'monospace', fontSize: 12 }}>#{t.trade_id}</td>
                          <td><span className="neon" style={{ fontWeight: 600 }}>{t.symbol || '—'}</span></td>
                          <td style={{ color: '#9ca3af' }}>{t.seller_name || t.seller_id}</td>
                          <td style={{ color: '#9ca3af' }}>{t.buyer_name  || t.buyer_id}</td>
                          <td style={{ fontWeight: 600 }}>${Number(t.price).toFixed(2)}</td>
                          <td>{riskBadge(t.risk_score || 0)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Risk Activity */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div className="glass" style={{ padding: 20 }}>
                  <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 16 }}>Risk Trend</div>
                  <MiniGraph logs={logs} />
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 8 }}>
                    <span style={{ color: '#4b5563', fontSize: 11 }}>Last 20 events</span>
                    <span className="neon" style={{ fontSize: 11, fontWeight: 600 }}>LIVE</span>
                  </div>
                </div>

                <div className="glass" style={{ overflow: 'hidden', flex: 1 }}>
                  <div style={{ padding: '16px 20px 12px', borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontWeight: 700, fontSize: 14 }}>Fraud Alerts</span>
                    <span className="badge badge-high">{logs.length}</span>
                  </div>
                  <div className="scroll-y" style={{ maxHeight: 220 }}>
                    {logs.slice(0, 8).map((l, i) => (
                      <div key={i} style={{ padding: '12px 20px', borderBottom: '1px solid rgba(255,255,255,0.03)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div style={{ fontSize: 12, fontWeight: 600, color: '#f87171' }}>Risk {l.risk_score}</div>
                          <div style={{ fontSize: 11, color: '#4b5563', marginTop: 2 }}>{(l.reason || '').slice(0, 30)}…</div>
                        </div>
                        {riskBadge(l.risk_score)}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Quick nav */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16 }}>
              {[
                { label: '🔁 Fraud Cycles', desc: 'Detected circular trading rings', path: '/fraud' },
                { label: '👤 Traders', desc: 'Risk scores and trader profiles', path: '/traders' },
                { label: '📋 All Transactions', desc: 'Full trade log with filters', path: '/transactions' },
              ].map((item, i) => (
                <div key={i} className="glass card-hover" style={{ padding: 24, cursor: 'pointer' }} onClick={() => navigate(item.path)}>
                  <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 6 }}>{item.label}</div>
                  <div style={{ color: '#6b7280', fontSize: 13 }}>{item.desc}</div>
                  <div className="neon" style={{ fontSize: 12, marginTop: 12 }}>Open →</div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
}
